//! AC4: bounded lifecycle and host parity with Python.
//!
//! Expected outcomes are generated by `tests/generate_rust_store_fixture.py`
//! from the REAL `share.broker_host.BrokerHostCoordinator` with an injected
//! clock and host ops; the Rust coordinator runs the same fakes.

use std::cell::RefCell;
use std::path::PathBuf;
use std::rc::Rc;

use serde_json::{json, Value};
use um_broker::host::{Clock, HostCoordinator, HostOps, MaintenanceLeaseStore};
use um_broker::publish::{InstanceChannel, InstanceRegistry};

fn fixture() -> Value {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../..")
        .join("tests/fixtures/rust_store_rev1.json");
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

struct FakeClock {
    value: RefCell<f64>,
}

impl Clock for FakeClock {
    fn now(&self) -> f64 {
        *self.value.borrow()
    }

    fn sleep(&self, seconds: f64) {
        *self.value.borrow_mut() += seconds;
    }
}

struct FakeHost {
    config: Value,
    calls: Rc<RefCell<Vec<Value>>>,
    running: RefCell<bool>,
    closed: RefCell<bool>,
    sequence: RefCell<Vec<Value>>,
}

impl FakeHost {
    fn new(config: &Value, calls: Rc<RefCell<Vec<Value>>>) -> Self {
        Self {
            config: config.clone(),
            calls,
            running: RefCell::new(
                config
                    .get("running")
                    .and_then(Value::as_bool)
                    .unwrap_or(true),
            ),
            closed: RefCell::new(
                config
                    .get("closed")
                    .and_then(Value::as_bool)
                    .unwrap_or(true),
            ),
            sequence: RefCell::new(
                config
                    .get("running_sequence")
                    .and_then(Value::as_array)
                    .cloned()
                    .unwrap_or_default(),
            ),
        }
    }

    fn record(&self, value: Value) {
        self.calls.borrow_mut().push(value);
    }
}

impl HostOps for FakeHost {
    fn start_host(&mut self, explicit: bool, _deadline_s: f64) -> Option<bool> {
        self.record(json!({"start_host": explicit}));
        *self.running.borrow_mut() = self
            .config
            .get("start_result")
            .and_then(Value::as_bool)
            .unwrap_or(true);
        Some(*self.running.borrow())
    }

    fn stop_host(&mut self, _deadline_s: f64) -> Option<bool> {
        self.record(json!({"stop_host": true}));
        *self.closed.borrow_mut() = self
            .config
            .get("closed")
            .and_then(Value::as_bool)
            .unwrap_or(true);
        *self.running.borrow_mut() = false;
        Some(
            self.config
                .get("stop_result")
                .and_then(Value::as_bool)
                .unwrap_or(true),
        )
    }

    fn verify_running(&mut self, _deadline_s: f64) -> Option<bool> {
        self.record(json!({"verify_running": true}));
        let mut sequence = self.sequence.borrow_mut();
        if !sequence.is_empty() {
            return sequence.remove(0).as_bool();
        }
        Some(*self.running.borrow())
    }

    fn verify_closed(&mut self, _deadline_s: f64) -> Option<bool> {
        self.record(json!({"verify_closed": true}));
        Some(*self.closed.borrow())
    }

    fn verify_limits_evidence(&mut self) -> Option<(Option<Value>, String)> {
        self.record(json!({"verify_limits_evidence": true}));
        self.config.get("limits_evidence").map(|evidence| {
            (
                evidence
                    .get("verdict")
                    .and_then(Value::as_bool)
                    .map(Value::Bool),
                evidence
                    .get("detail")
                    .and_then(Value::as_str)
                    .unwrap_or("ok")
                    .to_string(),
            )
        })
    }

    fn verify_limits(&mut self) -> Option<Option<bool>> {
        self.record(json!({"verify_limits": true}));
        self.config.get("limits").map(|value| value.as_bool())
    }

    fn read_watchdog(&mut self) -> Option<Value> {
        self.record(json!({"read_watchdog": true}));
        self.config.get("watchdog").cloned()
    }

    fn read_faults(&mut self) -> Option<Value> {
        self.record(json!({"read_faults": true}));
        self.config.get("faults").cloned()
    }

    fn repair_limits(&mut self) -> Option<Value> {
        self.record(json!({"repair_limits": true}));
        self.config.get("repair").cloned()
    }
}

struct FakeChannel {
    calls: Rc<RefCell<Vec<Value>>>,
    queue: Rc<RefCell<Vec<Value>>>,
}

impl InstanceChannel for FakeChannel {
    fn call(
        &mut self,
        action: &str,
        fields: &Value,
        instance_id: &str,
        _deadline_s: f64,
    ) -> Result<Value, String> {
        self.calls.borrow_mut().push(json!({
            "instance_call": {
                "action": action,
                "instance_id": instance_id,
                "fields": fields,
            },
        }));
        let mut queue = self.queue.borrow_mut();
        if queue.is_empty() {
            return Err("no scripted response".to_string());
        }
        Ok(queue.remove(0))
    }
}

#[test]
fn the_bounded_lifecycle_matches_python() {
    let fixture = fixture();
    for case in fixture["host"].as_array().unwrap() {
        let name = case["case"].as_str().unwrap();
        let config = &case["config"];
        let action = config["action"].as_str().unwrap();
        let clock = Box::new(FakeClock {
            value: RefCell::new(100.0),
        });
        let host_calls = Rc::new(RefCell::new(Vec::new()));
        let host = FakeHost::new(config, Rc::clone(&host_calls));
        let channel_calls = Rc::new(RefCell::new(Vec::new()));
        let responses: Vec<Value> = case["instance_responses"]
            .as_array()
            .cloned()
            .unwrap_or_default();
        let queue = Rc::new(RefCell::new(Vec::new()));
        *queue.borrow_mut() = responses;

        let mut registry = InstanceRegistry::default();
        for instance in case["instances"].as_array().cloned().unwrap_or_default() {
            registry.register(instance.as_str().unwrap()).unwrap();
        }
        let mut leases = MaintenanceLeaseStore::default();
        leases.set_now(100);
        let mut coordinator = HostCoordinator::new(
            host,
            FakeChannel {
                calls: Rc::clone(&channel_calls),
                queue,
            },
            registry,
            clock,
        )
        .with_leases(leases);
        let result = match action {
            "start" => coordinator.start(
                config
                    .get("explicit")
                    .and_then(Value::as_bool)
                    .unwrap_or(false),
            ),
            "drain" => coordinator.drain(),
            "emergency" => coordinator.emergency_stop(),
            "maintenance-begin" => coordinator.maintenance_begin(
                "share_gateway",
                config.get("lease_s").and_then(Value::as_i64).unwrap_or(300),
            ),
            "maintenance-end" => {
                let begin = coordinator.maintenance_begin("share_gateway", 300);
                let lease_id = begin.result()["lease_id"].as_str().unwrap().to_string();
                coordinator.maintenance_end("share_gateway", &lease_id)
            }
            "maintenance-status" => coordinator.maintenance_status(),
            "gateway-restart" => coordinator.gateway_restart(
                "share_gateway",
                config
                    .get("budget_s")
                    .and_then(Value::as_i64)
                    .unwrap_or(120),
            ),
            other => panic!("unexpected action {other}"),
        };
        assert_eq!(
            result.to_value(),
            case["result"],
            "case '{name}' result differs from Python"
        );
        assert_eq!(
            json!(host_calls.borrow().clone()),
            case["host_calls"],
            "case '{name}' host calls differ from Python"
        );
        assert_eq!(
            json!(channel_calls.borrow().clone()),
            case["instance_calls"],
            "case '{name}' instance calls differ from Python"
        );
    }
}

#[test]
fn a_verified_closure_clears_the_lease_and_bumps_the_epoch() {
    let directory = tempfile::tempdir().unwrap();
    let clock = Box::new(FakeClock {
        value: RefCell::new(100.0),
    });
    let mut registry = InstanceRegistry::default();
    registry.register("i-1").unwrap();
    let host_calls = Rc::new(RefCell::new(Vec::new()));
    let host = FakeHost::new(
        &json!({"running": true, "closed": true}),
        Rc::clone(&host_calls),
    );
    let queue = Rc::new(RefCell::new(vec![
        json!({"ok": true, "error_code": "ok", "result": {"state": "running", "active_count": 1}}),
        json!({"ok": true, "error_code": "ok", "result": {"state": "draining"}}),
        json!({"ok": true, "error_code": "ok", "result": {"state": "running", "active_count": 1}}),
    ]));
    let mut coordinator = HostCoordinator::new(
        host,
        FakeChannel {
            calls: Rc::new(RefCell::new(Vec::new())),
            queue,
        },
        registry,
        clock,
    );
    let begin = coordinator.maintenance_begin("share_gateway", 300);
    assert!(begin.ok_flag());
    assert!(coordinator.maintenance_record()["state"].as_str() == Some("leased"));
    let emergency = coordinator.emergency_stop();
    assert!(emergency.ok_flag());
    assert!(coordinator.maintenance_record()["state"].as_str() == Some("idle"));
    assert!(coordinator.leases_mut().current().is_none());
    let _ = directory;
}

fn coordinator_with(
    config: Value,
) -> (
    HostCoordinator<FakeHost, FakeChannel>,
    Rc<RefCell<Vec<Value>>>,
) {
    let clock = Box::new(FakeClock {
        value: RefCell::new(100.0),
    });
    let host_calls = Rc::new(RefCell::new(Vec::new()));
    let host = FakeHost::new(&config, Rc::clone(&host_calls));
    let channel_calls = Rc::new(RefCell::new(Vec::new()));
    let mut registry = InstanceRegistry::default();
    registry.register("i-1").unwrap();
    let coordinator = HostCoordinator::new(
        host,
        FakeChannel {
            calls: Rc::clone(&channel_calls),
            queue: Rc::new(RefCell::new(Vec::new())),
        },
        registry,
        clock,
    );
    (coordinator, host_calls)
}

#[test]
fn host_verify_and_stop_require_verified_evidence() {
    let (mut running, _) = coordinator_with(json!({"running": true, "closed": true}));
    assert_eq!(
        running.host_verify("running").to_value()["result"]["host_running"],
        json!(true)
    );
    assert_eq!(
        running.host_verify("closed").to_value()["result"]["host_closed"],
        json!(true)
    );

    let (mut stopped, _) = coordinator_with(json!({"stop_result": true, "closed": true}));
    assert!(stopped.host_stop().ok_flag());
    let (mut unverified, _) = coordinator_with(json!({"stop_result": true, "closed": false}));
    assert_eq!(
        unverified.host_stop().to_value()["error_code"],
        json!("unconfirmed")
    );
    let (mut refused, _) = coordinator_with(json!({"stop_result": false}));
    assert_eq!(
        refused.host_stop().to_value()["error_code"],
        json!("unconfirmed")
    );
}

#[test]
fn limits_repair_and_host_evidence_never_fabricate() {
    let (mut missing, _) = coordinator_with(json!({}));
    assert_eq!(
        missing.host_repair_limits().to_value()["error_code"],
        json!("capability_missing")
    );
    let (mut repaired, _) = coordinator_with(json!({"repair": {"repaired": true}}));
    assert_eq!(
        repaired.host_repair_limits().to_value()["result"],
        json!({"repaired": true, "code": "ok"})
    );
    let (mut refused, _) =
        coordinator_with(json!({"repair": {"repaired": false, "code": "unconfirmed"}}));
    assert_eq!(
        refused.host_repair_limits().to_value()["error_code"],
        json!("unconfirmed")
    );

    let (mut watchdog, _) =
        coordinator_with(json!({"watchdog": {"query_error": "wfp_unavailable"}}));
    let evidence = watchdog.host_evidence("watchdog").to_value();
    assert_eq!(
        evidence["result"]["verdict"],
        json!({"query_error": "wfp_unavailable"})
    );
    assert_eq!(evidence["result"]["detail"], json!("wfp_unavailable"));

    let (mut limits, _) = coordinator_with(
        json!({"limits_evidence": {"verdict": null, "detail": "limits_unavailable"}}),
    );
    let evidence = limits.host_evidence("limits").to_value();
    assert_eq!(evidence["result"]["verdict"], Value::Null);
    assert_eq!(evidence["result"]["detail"], json!("limits_unavailable"));

    let (mut faults, _) = coordinator_with(json!({}));
    let evidence = faults.host_evidence("faults").to_value();
    assert_eq!(evidence["result"]["verdict"], Value::Null);
    assert_eq!(evidence["result"]["detail"], json!("fault_log_absent"));
}
